'use strict';
const Arrival=require('./arrival-triggers');const SCHEMA='timed-course-120/v1';const isTimed=m=>m?.schema===SCHEMA;
function validate(m){if(m.durationTicks!==14400||m.winMode!=='timed-route'||!m.worldBounds||m.worldBounds.minX!==0||m.worldBounds.maxX!==m.width||!Array.isArray(m.routeMarks)||!m.routeMarks.length||!Array.isArray(m.macroPlan)||!Array.isArray(m.encounters)||!Array.isArray(m.triggers))throw Error('Invalid timed-course contract');let end=0;for(const w of m.macroPlan){if(w.startTick!==end||!Number.isInteger(w.endTick)||w.endTick<=end)throw Error('Macro timeline gap/overlap');end=w.endTick;}if(end!==14400)throw Error('Macro duration mismatch');const ids=new Set();let last=-1;for(const r of m.routeMarks){if(typeof r.id!=='string'||ids.has(r.id)||!Number.isFinite(r.x)||r.x<=last||r.x<0||r.x>m.width||r.yMin!==10||r.yMax!==530||r.direction!=='forward'||r.portalPolicy!=='physical-crossing-only')throw Error('Invalid public route');last=r.x;ids.add(r.id);}Arrival.validate(m);}
function initialState(){return{routeProgress:0,routeCrossings:[],triggerState:{},terminal:null,physicsSubsteps:0};}
function crossRoute(m,s,before,teleported){Arrival.cross(m,s,before,teleported);if(teleported)return;let r;while((r=m.routeMarks[s.routeProgress])&&before.x<r.x&&s.x>=r.x){const u=(r.x-before.x)/(s.x-before.x),y=before.y+u*(s.y-before.y);if(y>=r.yMin&&y<=r.yMax){s.routeCrossings.push({id:r.id,tick:s.tick,x:r.x,y});s.events.push({type:'route_cross',id:r.id,tick:s.tick});s.routeProgress++;}else break;}}
function finishTick(m,s){if(!s.alive){s.terminal='death';return;}if(s.x<m.worldBounds.minX||s.x>m.worldBounds.maxX){s.alive=false;s.terminal='world-boundary';s.events.push({type:'death',id:'world-boundary',tick:s.tick});return;}if(s.tick>=m.durationTicks){s.won=s.routeProgress===m.routeMarks.length;s.terminal=s.won?'complete120':'incomplete-route';}}
function validateState(m,s){Arrival.validateState(m,s);if(!Number.isInteger(s.routeProgress)||s.routeProgress<0||s.routeProgress>m.routeMarks.length||!Array.isArray(s.routeCrossings)||s.routeCrossings.length!==s.routeProgress||s.tick>14400||s.routeCrossings.some((r,i)=>r.id!==m.routeMarks[i].id))throw Error('Invalid timed checkpoint');if(s.won&&(s.tick!==14400||!s.alive||s.routeProgress!==m.routeMarks.length))throw Error('Invalid timed win checkpoint');}
module.exports={isTimed,validate,initialState,crossRoute,finishTick,validateState};
